"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import {
  PlugsConnectedIcon as PhPlug,
  LockSimpleIcon as PhLock,
  CalendarIcon as PhCalendar,
  CheckIcon as PhCheck,
} from "@phosphor-icons/react";

interface ScopeDef {
  id: string;
  label: string;
  detail: string;
}

const SCOPES: ScopeDef[] = [
  { id: "read-events", label: "Read your events", detail: "See event titles, times, and attendees." },
  { id: "write-events", label: "Create and edit events", detail: "Add, move, or cancel events on your behalf." },
  { id: "read-contacts", label: "Read your contacts", detail: "Look up names to suggest attendees." },
];

function PlugIcon() {
  return <PhPlug size={15} weight="fill" aria-hidden />;
}
function LockIcon() {
  return <PhLock size={11} aria-hidden />;
}
function CalendarIcon() {
  return <PhCalendar size={13} aria-hidden />;
}
function CheckIcon() {
  return <PhCheck size={11} aria-hidden />;
}

interface ScopePreviewProps {
  className?: string;
}

export function ScopePreview({ className }: ScopePreviewProps) {
  const [enabled, setEnabled] = useState<Record<string, boolean>>({
    "read-events": true,
    "write-events": false,
    "read-contacts": false,
  });
  const [hovered, setHovered] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();

  const toggle = (id: string) => {
    setEnabled((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const hasReadEvents = enabled["read-events"];
  const hasWriteEvents = enabled["write-events"];
  const hasReadContacts = enabled["read-contacts"];
  const canAdd = hasReadEvents && hasWriteEvents;

  const powers = (ids: string[]) => hovered !== null && ids.includes(hovered);

  return (
    <div className={className}>
      <div className="w-full rounded-2xl border border-slate-200/70 bg-white/95 p-5 shadow-sm backdrop-blur-xl dark:border-white/10 dark:bg-neutral-950/80">
        <h3 className="flex items-center gap-1.5 text-sm font-semibold text-slate-900 dark:text-white">
          <PlugIcon />
          Connect Calendar
        </h3>

        <div className="mt-3 space-y-1">
          {SCOPES.map((scope) => {
            const on = enabled[scope.id];
            return (
              <div
                key={scope.id}
                onMouseEnter={() => setHovered(scope.id)}
                onMouseLeave={() => setHovered((h) => (h === scope.id ? null : h))}
                className={`flex items-start gap-2.5 rounded-lg p-2 transition-colors ${
                  on ? "bg-emerald-50/70 dark:bg-emerald-500/10" : ""
                }`}
              >
                <motion.button
                  type="button"
                  role="switch"
                  aria-checked={on}
                  aria-label={scope.label}
                  onClick={() => toggle(scope.id)}
                  onFocus={() => setHovered(scope.id)}
                  onBlur={() => setHovered((h) => (h === scope.id ? null : h))}
                  whileTap={shouldReduceMotion ? undefined : { scale: 0.93 }}
                  className={`relative mt-0.5 h-5 w-9 shrink-0 rounded-full transition-colors duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
                    on ? "bg-emerald-600" : "bg-slate-300 dark:bg-slate-600"
                  }`}
                >
                  <motion.span
                    animate={{ x: on ? 17 : 2 }}
                    transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 700, damping: 32 }}
                    className="absolute top-0.5 block h-4 w-4 rounded-full bg-white shadow-sm"
                  />
                </motion.button>
                <span className="min-w-0 flex-1">
                  <span className="block text-xs font-medium text-slate-800 dark:text-slate-100">{scope.label}</span>
                  <span className="block text-[11px] text-slate-500 dark:text-slate-400">{scope.detail}</span>
                </span>
              </div>
            );
          })}
        </div>

        <div className="mt-4 rounded-xl border border-slate-200/70 bg-slate-50/70 p-3.5 dark:border-white/10 dark:bg-white/[0.03]">
          <p className="text-[11px] font-medium uppercase tracking-wide text-slate-400 dark:text-slate-500">
            Preview: what this could do
          </p>

          <p className="mt-2 text-xs text-slate-600 dark:text-slate-300">
            Team Sync request from{" "}
            <motion.span
              animate={powers(["read-contacts"]) && !shouldReduceMotion ? { scale: 1.04 } : { scale: 1 }}
              className={`inline-block rounded px-0.5 font-medium transition-colors ${
                powers(["read-contacts"])
                  ? "bg-emerald-200/60 text-emerald-800 dark:bg-emerald-500/20 dark:text-emerald-300"
                  : "text-slate-700 dark:text-slate-200"
              }`}
            >
              {hasReadContacts ? "Alex Chen" : "alex@co.com"}
            </motion.span>
            , Friday 2:00 PM.
          </p>

          <div
            className={`mt-2 flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-xs transition-all ${
              powers(["read-events"]) ? "ring-1 ring-emerald-400/60" : ""
            } ${
              hasReadEvents
                ? "bg-emerald-50/80 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-300"
                : "bg-white/60 text-slate-400 dark:bg-white/[0.03] dark:text-slate-500"
            }`}
          >
            {hasReadEvents ? <CheckIcon /> : <LockIcon />}
            {hasReadEvents ? "Checked, your calendar is free then." : "Could check your calendar for conflicts."}
          </div>

          <div
            className={`mt-2 flex items-center justify-between gap-2 rounded-lg bg-white/60 px-2 py-1.5 transition-all dark:bg-white/[0.03] ${
              powers(["read-events", "write-events"]) ? "ring-1 ring-emerald-400/60" : ""
            }`}
          >
            <span className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
              <CalendarIcon />
              {canAdd ? "Ready to add to your calendar." : "Requires read + create access."}
            </span>
            <span
              className={`inline-flex shrink-0 items-center gap-1 rounded-md px-2 py-1 text-[11px] font-medium transition-colors ${
                canAdd ? "bg-emerald-600 text-white" : "bg-slate-200 text-slate-400 dark:bg-white/10 dark:text-slate-500"
              }`}
            >
              {canAdd ? <CheckIcon /> : <LockIcon />}
              Add to calendar
            </span>
          </div>
        </div>
      </div>
      <p className="text-center text-xs text-slate-400 dark:text-slate-500">
        Toggle a scope and the preview recomputes live, hover one to see exactly which parts of the example it powers, alone or combined with another.
      </p>
    </div>
  );
}
